def solve(rows):
    state = 2
    kept_rows = []
    for i, row in enumerate(rows):
        weight = 0
        if isinstance(row, int):
            weight = row
        elif isinstance(row, str) and row.startswith("|") and row.endswith("|"):
            try:
                weight = int(row[1:-1])
            except ValueError:
                weight = 0
        elif isinstance(row, list):
            for item in row:
                if isinstance(item, int):
                    weight += item
                elif isinstance(item, str):
                    weight += len(item)

        if (state + weight + i) % 11 != 10 or i == len(rows) - 1:
            kept_rows.append(row)

        if weight == 0:
            state = 2
        else:
            state = (3 * state + weight) % 11

    if not kept_rows:
        return []

    final_state = state
    kept_length = len(kept_rows)
    rotation_amount = final_state % kept_length
    rotated_kept_rows = kept_rows[rotation_amount:] + kept_rows[:rotation_amount]

    aggregated_amounts = {}
    for row in rotated_kept_rows:
        if isinstance(row, list) and len(row) >= 3:
            key = row[0]
            amount = row[1]
            void = row[2]
            if not void and abs(amount) >= 4:
                if key in aggregated_amounts:
                    aggregated_amounts[key] += amount
                else:
                    aggregated_amounts[key] = amount

    result = []
    for key, total in aggregated_amounts.items():
        if total != 0:
            result.append([key, total])

    result.sort()
    return result

